```
class PasswordGenerator {
  constructor(minLength = 8, maxLength = 128) {
    this.minLength = minLength;
    this.maxLength = maxLength;
    this.pools = {
      lowercase: 'abcdefghijklmnopqrstuvwxyz',
      uppercase: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
      digits: '0123456789',
      specialChars: '!@#$%^&*()_+-={}|[]:;<>?,./'
    };
    this.characterSets = {
      'default': [this.pools.lowercase, this.pools.digits, this.pools.specialChars],
      'strong': [this.pools.lowercase, this.pools.digits, this.pools.specialChars, this.pools.uppercase]
    };
  }

  generatePassword(length = this.minLength, characterSet = 'default') {
    const set = this.characterSets[characterSet] || this.characterSets.default;
    const password = [];
    for (let i = 0; i < length; i++) {
      const pool = set[Math.floor(Math.random() * set.length)];
      const char = pool.charAt(Math.floor(Math.random() * pool.length));
      password.push(char);
    }
    return password.join('');
  }

  getStrongPassword() {
    return this.generatePassword(this.maxLength, 'strong');
  }

  getRandomPassword() {
    return this.generatePassword();
  }
}
