const int N = 1000; // Размер шага по x
const int N_THREADS = 4; // Количество потоков
const double a = 0.0; // Нижняя граница интегрирования
const double b = 1.0; // Верхняя граница интегрирования
const double f(double x) { return x * x; } // Функция, которая интегрируется

double integral(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        double x = a + i * h;
        sum += f(x);
    }
    return sum * h;
}

double integral_rectangles(double (*f)(double), double a, double b, int n) {
    return integral(f, a, b, n);
}

double integral_trapezium(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        double x = a + i * h;
        sum += f(x);
    }
    return (h / 2) * (f(a) + 2 * sum + f(b));
}

double integral_simpson(double (*f)(double), double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        double x = a + i * h;
        if ((i % 2) == 0) {
            sum += f(x);
        } else if ((i % 2) == 1) {
            sum += 2 * f(x);
        }
    }
    return (h / 3) * (f(a) + f(b) + 2 * sum);
}

