    HANDLE semaphore = CreateSemaphore(NULL, 0, N_THREADS, NULL);

    double result_rectangles[N_THREADS];
    double result_trapezium[N_THREADS];
    double result_simpson[N_THREADS];

    for (int i = 0; i < N_THREADS; i++) {
        HANDLE thread = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)&thread_func, (LPVOID)&i, 0, NULL);
        WaitForSingleObject(thread, INFINITE);
        CloseHandle(thread);
    }

    WaitForSingleObject(semaphore, INFINITE);
    CloseHandle(semaphore);
    CloseHandle(mutex);

    std::cout << "Results:" << std::endl;
    for (int i = 0; i < N_THREADS; i++) {
        std::cout << "Rectangles: " << result_rectangles[i] << std::endl;
        std::cout << "Trapezium: " << result_trapezium[i] << std::endl;
        std::cout << "Simpson: " << result_simpson[i] << std::endl;
    }

    return 0;
}

